type PaymentMethod = 'CASH' | 'BANK' | 'CARD' | 'EWALLET';
type DebtType = 'RECEIVABLE' | 'PAYABLE';

interface FinanceTransaction {
  id: string;
  date: string;
  time: string;
  type: TransactionType;
  category: string;
  description: string;
  amount: number;
  branch: BranchCode;
  method: PaymentMethod;
  cashbook: string;
  reference: string;
  counterparty: string;
  status: TransactionStatus;
  createdBy: string;
  approvedBy: string;
  note: string;
}

interface Cashbook {
  id: string;
  name: string;
  type: PaymentMethod;
  branch: BranchCode | 'ALL';
  opening: number;
  income: number;
  expense: number;
  pending: number;
  lastReconciled: string;
  account: string;
}

interface DebtItem {
  id: string;
  type: DebtType;
  name: string;
  category: string;
  branch: BranchCode;
  total: number;
  paid: number;
  dueDate: string;
  status: 'OPEN' | 'OVERDUE' | 'PARTIAL';
  reference: string;
  owner: string;
}

interface BudgetItem {
  id: string;
  category: string;
  branch: BranchCode | 'ALL';
  budget: number;
  actual: number;
  forecast: number;
  owner: string;
}

